"""Markdown generators for architecture.md, file-map.md, and dependencies.md."""

from __future__ import annotations

from pathlib import Path

from groma.graph import DependencyGraph
from groma.schema import FileIndex, Manifest

GROMA_DIR_NAME = ".groma"


def generate_architecture_doc(
    manifest: Manifest, file_index: FileIndex, graph: DependencyGraph
) -> str:
    """Generate .groma/architecture.md content."""
    lines: list[str] = [
        f"# {manifest.project_name} — System Architecture & Core Map",
        "",
        "> Deterministically generated by **Groma**.",
        "",
        "## 1. Project Overview",
        "",
        f"- **Project Name**: `{manifest.project_name}`",
        f"- **Generated At (UTC)**: `{manifest.generated_at}`",
        f"- **Summary Fingerprint**: `{manifest.fingerprint}`",
        f"- **Tracked Source Files**: {len(manifest.files)}",
    ]

    total_loc = sum(f.lines_of_code for f in file_index.files.values())
    lines.append(f"- **Total Lines of Code**: {total_loc:,}")

    if manifest.languages:
        lang_badges = ", ".join(f"`{lang}`" for lang in manifest.languages)
        lines.append(f"- **Indexed Languages**: {lang_badges}")
    else:
        lines.append("- **Indexed Languages**: None detected")

    lines.extend(["", "---", "", "## 2. Core Modules & Hubs (Highest Centrality)", ""])

    hubs = graph.core_hubs(limit=15)
    if hubs:
        lines.extend(
            [
                "These files have the highest Fan-In (in-degree), meaning they are imported most heavily by other modules in this repository.",
                "",
                "| Rank | File Path | In-Degree (Dependents) | Summary / Responsibility |",
                "| :--- | :--- | :--- | :--- |",
            ]
        )
        for rank, (path, in_deg) in enumerate(hubs, start=1):
            analysis = file_index.files.get(path)
            doc = (
                analysis.module_docstring
                if (analysis and analysis.module_docstring)
                else "*(No module docstring)*"
            )
            # Escape pipe characters for markdown table safety
            doc_escaped = doc.replace("|", "\\|")
            lines.append(f"| {rank} | `{path}` | **{in_deg}** | {doc_escaped} |")
    else:
        lines.append("*No cross-file import relationships detected among tracked source files.*")

    lines.extend(["", "---", "", "## 3. HTTP API Endpoints & Routes", ""])

    # Collect all routes across all files
    all_routes: list[tuple[str, str, str, str, int]] = []
    for path, analysis in sorted(file_index.files.items()):
        for r in analysis.routes:
            all_routes.append((r.method, r.path, r.handler, path, r.line))

    if all_routes:
        lines.extend(
            [
                "| Method | Path | Handler | Source Location |",
                "| :--- | :--- | :--- | :--- |",
            ]
        )
        for method, route_path, handler, path, line in all_routes:
            lines.append(
                f"| `{method}` | `{route_path}` | `{handler}` | `{path}:{line}` |"
            )
    else:
        lines.append("*No HTTP route decorators detected.*")

    lines.append("")
    return "\n".join(lines)


def _format_function_signature(func_name: str, params: list[str], return_type: str | None) -> str:
    """Format a clean Python function signature string."""
    params_str = ", ".join(params)
    sig = f"{func_name}({params_str})"
    if return_type:
        sig += f" -> {return_type}"
    return sig


def generate_file_map_doc(file_index: FileIndex) -> str:
    """Generate .groma/file-map.md content with complete classes, methods, and functions."""
    lines: list[str] = [
        f"# {file_index.project_name} — Codebase File & Symbol Map",
        "",
        "> Deterministically generated by **Groma**. Detailed structural map of all symbols and line numbers.",
        "",
    ]

    for rel_path, analysis in sorted(file_index.files.items()):
        lines.extend([
            f"## `{rel_path}`",
            "",
            f"- **Language**: `{analysis.language}` | **Lines**: {analysis.lines_of_code} | **Size**: {analysis.size:,} bytes",
        ])

        if analysis.module_docstring:
            lines.append(f"- **Module Docstring**: *{analysis.module_docstring}*")

        # Classes
        if analysis.classes:
            lines.extend(["", "### Classes", ""])
            for cls in analysis.classes:
                base_str = f"({', '.join(cls.bases)})" if cls.bases else ""
                lines.append(f"- **`class {cls.name}{base_str}`** (lines {cls.start_line}–{cls.end_line})")
                if cls.docstring:
                    lines.append(f"  - *{cls.docstring}*")
                if cls.methods:
                    for m in cls.methods:
                        async_prefix = "async " if m.is_async else ""
                        sig = _format_function_signature(m.name, m.params, m.return_type)
                        lines.append(f"  - `{async_prefix}def {sig}` (lines {m.start_line}–{m.end_line})")
                        if m.docstring:
                            lines.append(f"    - *{m.docstring}*")

        # Standalone Functions
        if analysis.functions:
            lines.extend(["", "### Top-Level Functions", ""])
            for f in analysis.functions:
                async_prefix = "async " if f.is_async else ""
                sig = _format_function_signature(f.name, f.params, f.return_type)
                lines.append(f"- `{async_prefix}def {sig}` (lines {f.start_line}–{f.end_line})")
                if f.docstring:
                    lines.append(f"  - *{f.docstring}*")

        if not analysis.classes and not analysis.functions:
            lines.extend(["", "*(No top-level classes or functions declared)*", ""])

        lines.extend(["", "---", ""])

    return "\n".join(lines)


def generate_dependencies_doc(graph: DependencyGraph) -> str:
    """Generate .groma/dependencies.md content detailing per-file imports and dependents."""
    lines: list[str] = [
        f"# {graph.file_index.project_name} — Dependency & Impact Map",
        "",
        "> Deterministically generated by **Groma** using NetworkX import resolution.",
        "",
        "## Dependency Relationships by File",
        "",
    ]

    for rel_path in sorted(graph.file_index.files.keys()):
        imports = graph.imports_of(rel_path)
        imported_by = graph.imported_by(rel_path)

        lines.extend([
            f"### `{rel_path}`",
            "",
        ])

        if imports:
            lines.append("**Imports (Outgoing Dependencies):**")
            for imp in imports:
                lines.append(f"- `{imp}`")
        else:
            lines.append("**Imports (Outgoing Dependencies):** None (isolated from internal imports)")

        lines.append("")

        if imported_by:
            lines.append(f"**Imported By ({len(imported_by)} Dependents):**")
            for dep in imported_by:
                lines.append(f"- `{dep}`")
        else:
            lines.append("**Imported By:** None (Leaf node or top-level entrypoint)")

        lines.extend(["", "---", ""])

    return "\n".join(lines)


def render_markdown_docs(
    repo_root: Path,
    manifest: Manifest,
    file_index: FileIndex,
    graph: DependencyGraph,
) -> dict[str, Path]:
    """Render all 3 markdown files into <repo_root>/.groma/ and return their paths."""
    out_dir = repo_root.resolve() / GROMA_DIR_NAME
    out_dir.mkdir(parents=True, exist_ok=True)

    arch_path = out_dir / "architecture.md"
    file_map_path = out_dir / "file-map.md"
    deps_path = out_dir / "dependencies.md"

    arch_content = generate_architecture_doc(manifest, file_index, graph)
    file_map_content = generate_file_map_doc(file_index)
    deps_content = generate_dependencies_doc(graph)

    arch_path.write_text(arch_content, encoding="utf-8")
    file_map_path.write_text(file_map_content, encoding="utf-8")
    deps_path.write_text(deps_content, encoding="utf-8")

    return {
        "architecture": arch_path,
        "file_map": file_map_path,
        "dependencies": deps_path,
    }
